import io.vertx.junit5.VertxExtension;
import io.vertx.junit5.VertxTestContext;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.net.Socket;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;

@ExtendWith(VertxExtension.class)
@Execution(ExecutionMode.SAME_THREAD)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(70 * 1000)
@EnabledIfSystemProperty(named = "system.bootstrap.type", matches = "LOG_COLLECTOR")
public class TestLogCollector
{
    private static final Logger LOGGER = new Logger(RemoteEventForwarder.class, GlobalConstants.MOTADATA_EVENT_BUS, "Remote Event Forwarder");
    private static MessageConsumer<JsonObject> eventDBWriteTestConsumer;

    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {
        try
        {
            testContext.awaitCompletion(10, TimeUnit.SECONDS);

            var deploymentId = Bootstrap.getDeployedVerticles().get(RemoteEventForwarder.class.getSimpleName() + " 9450");

            Bootstrap.vertx().undeploy(deploymentId, result ->
            {
                if (result.succeeded())
                {
                    var deploymentId1 = Bootstrap.getDeployedVerticles().get(RemoteEventForwarder.class.getSimpleName() + " 9449");

                    Bootstrap.vertx().undeploy(deploymentId1, result1 ->
                    {
                        if (result1.succeeded())
                        {
                            Bootstrap.vertx().eventBus().publish(EVENT_CONFIG_INIT, new JsonObject().put(STATUS, STATUS_SUCCEED));

                            testContext.completeNow();
                        }
                    });
                }
            });


        }
        catch (Exception exception)
        {
            testContext.failNow(exception);
        }
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    @Timeout(5000)
    void testLogCollector(VertxTestContext testContext) throws InterruptedException
    {

        testContext.awaitCompletion(5, TimeUnit.SECONDS);

        eventDBWriteTestConsumer = TestUtil.vertx().eventBus().localConsumer(EventBusConstants.EVENT_REMOTE, message -> //this event will be
        {
            try
            {
                var event = message.body();

                Assertions.assertNotNull(event);

                Assertions.assertEquals(EVENT_LOG, event.getString(EVENT_TYPE));

                Assertions.assertEquals(155, event.getInteger(EVENT_VOLUME_BYTES));

                Assertions.assertEquals(DatastoreConstants.PluginId.UNKNOWN_LOG_EVENT.getName(), event.getInteger(PLUGIN_ID));

                eventDBWriteTestConsumer.unregister();

                testContext.completeNow();
            }
            catch (Exception exception)
            {
                testContext.failNow(exception);
            }
        });

        try (var socket = new Socket("localhost", MotadataConfigUtil.getTCPPort()))
        {
            var outputStream = socket.getOutputStream();

            outputStream.write("<85>Sep  7 16:42:04 smit-HP-EliteBook-840-G2 su: pam_unix(su:auth): authentication failure; logname= uid=1000 euid=0 tty=pts/1 ruser=smit rhost=  user=root".getBytes());

            outputStream.flush();

        }
        catch (Exception exception)
        {
            testContext.failNow(exception);
        }

        Assertions.assertTrue(testContext.awaitCompletion(15, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }
}

