    // testcase to set build pipeline address & start RPE. Disable it in local to avoid unnecessary process spawning
    // format for cli arguments : ipv4_address username password
    @Test
    @Order(1)
    @EnabledIfSystemProperty(named = "system.startup.mode", matches = "^APP|^MASTER|SLAVE$")
    void testSetBuildPipelineIPAddressAndStartRPE(VertxTestContext testContext)
    {
        Process process = null;

        var valid = false;

        try (DatagramSocket socket = new DatagramSocket())
        {

            socket.connect(InetAddress.getByName("8.8.8.8"), 1366);

            var ipAddress = socket.getLocalAddress().getHostAddress();

            if (ipAddress != null && !ipAddress.isEmpty() && (ipAddress.equalsIgnoreCase("172.16.8.158") || ipAddress.equalsIgnoreCase("172.16.8.156")))
            {
                LOGGER.debug("setting build pipeline ip address : " + ipAddress);

                System.setProperty("build.pipeline.ipv4.address", ipAddress);

                var processBuilder = new ProcessBuilder(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "collectorscript", ipAddress.equalsIgnoreCase("172.16.8.158") ? "172.16.8.235" : "172.16.9.208", "motadata", "motadata");

                process = processBuilder.start();

                if (process.waitFor(100, TimeUnit.SECONDS))
                {
                    BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));

                    if (inputReader.readLine().equalsIgnoreCase(STATUS_SUCCEED))
                    {
                        valid = true;

                        System.out.println("current running build pipeline address is " + ipAddress);

                        testContext.completeNow();
                    }
                    else
                    {
                        LOGGER.info("failed to start motadata RPE");
                    }
                }
                else
                {
                    LOGGER.info("failed to start motadata RPE because process timed out");

                    process.destroyForcibly();
                }
            }
            else
            {
                LOGGER.debug("Unknown ipv4 address found for build pipeline :" + ipAddress);

                testContext.failNow("Unknown ipv4 address found for build pipeline " + ipAddress);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            testContext.failNow(exception.getMessage());
        }
        finally
        {

            if (process != null && process.isAlive())
            {
                process.destroyForcibly();
            }

            if (!valid)
            {
                testContext.failNow("failed to start motadata RPE calling System.exit(0)");

                System.exit(0);
            }
        }
    }

