package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.util.CodecUtil;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.nio.MappedByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.StandardOpenOption;
import java.util.Arrays;

import static com.mindarray.GlobalConstants.PATH_SEPARATOR;
import static com.mindarray.GlobalConstants.VALUE_SEPARATOR_WITH_ESCAPE;

public class EventStore
{
    private static final Logger LOGGER = new Logger(EventStore.class, GlobalConstants.MOTADATA_EVENT_BUS, "Event Store");
    private int segments;
    private String name;
    private MappedByteBuffer[] reader;
    private MappedByteBuffer[] writer;
    private int[] readingOffset;
    private int[] writingOffset;
    private int writingSegment;
    private int readingSegment;
    private FileChannel[] readerChannel;
    private FileChannel[] writerChannel;
    private int[] pendingEvents;
    private int[] droppedEvents;
    private final int segmentSize;
    private String path;

    protected EventStore(String path)
    {
        this.path = path;

        switch (MotadataConfigUtil.getDeploymentType())
        {
            case 0:
            {
                this.segmentSize = 32 * 1024 * 1024;

                break;
            }
            case 1:
            {
                this.segmentSize = 64 * 1024 * 1024;

                break;
            }
            case 2:
            {
                this.segmentSize = 128 * 1024 * 1024;

                break;
            }
            default:
            {
                this.segmentSize = 32 * 1024 * 1024;
            }
        }
    }

    protected void put(JsonObject event) throws Exception
    {
        put(CodecUtil.compress(event.encode()));
    }

    protected void put(byte[] bytes) throws Exception
    {
        try
        {
            if (writer != null)
            {
                if (writingOffset[writingSegment] + bytes.length + 4 <= segmentSize)
                {
                    if (writingSegment != readingSegment)
                    {
                        writer[writingSegment].putInt(writingOffset[writingSegment] - 4, bytes.length);

                        writer[writingSegment].put(writingOffset[writingSegment], bytes);

                        writingOffset[writingSegment] += bytes.length;

                        writer[writingSegment].putInt(writingOffset[writingSegment], Integer.MIN_VALUE); //EOF

                        writingOffset[writingSegment] += 4;

                        pendingEvents[writingSegment] += 1;

                    }
                    else
                    {
                        if (writingOffset[writingSegment] < readingOffset[readingSegment])
                        {
                            droppedEvents[writingSegment] += pendingEvents[writingSegment];

                            pendingEvents[writingSegment] = 0;

                            rolloverReadingSegment();

                            LOGGER.debug(String.format("rollover reading %s segment of %s due to slow reading...", readingSegment,name));

                        }

                        writer[writingSegment].putInt(writingOffset[writingSegment]- 4, bytes.length);

                        writer[writingSegment].put(writingOffset[writingSegment], bytes);

                        writingOffset[writingSegment] += bytes.length;

                        writer[writingSegment].putInt(writingOffset[writingSegment], Integer.MIN_VALUE); //EOF

                        writingOffset[writingSegment] += 4;

                        pendingEvents[writingSegment] += 1;
                    }
                }
                else
                {
                    writer[writingSegment].clear();

                    writerChannel[writingSegment].close();

                    LOGGER.debug(String.format("before rollover writing %s segment of %s due to segment size overlapped...", writingSegment,name));

                    droppedEvents[writingSegment] += pendingEvents[writingSegment];

                    writingSegment += 1;

                    if (writingSegment == segments)
                    {
                        writingSegment = 0;
                    }

                    if (writingSegment == readingSegment)
                    {
                        rolloverReadingSegment();
                    }

                    pendingEvents[writingSegment] = 0;

                    LOGGER.debug(String.format("after rollover writing %s segment of %s due to segment size overlapped...", writingSegment,name));

                    writingOffset[writingSegment] = 0;

                    writer[writingSegment].putInt(writingOffset[writingSegment], Integer.MIN_VALUE); //EOF

                    writingOffset[writingSegment] += 4;

                    put(bytes);
                }
            }
            else
            {
                throw new Exception("writer is null...");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected byte[] get() throws Exception
    {
        byte[] bytes = null;

        try
        {
            if (reader != null)
            {
                if (readingSegment == writingSegment)
                {
                    if (readingOffset[readingSegment] < writingOffset[writingSegment])
                    {
                        bytes = readBytes();
                    }
                }
                else
                {
                    bytes = readBytes();

                    if (bytes ==null)
                    {
                        LOGGER.debug(String.format("rollover reading %s segment of %s due to read segment end of the file...", readingSegment,name));

                        rolloverReadingSegment();

                        bytes = get();
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.warn(String.format("corrupted event received in %s",name));

            LOGGER.error(exception);
        }

        return bytes;
    }

    protected EventStore setMaxSegments(int segments)
    {
        this.segments = segments;

        this.pendingEvents = new int[segments];

        this.droppedEvents = new int[segments];

        return this;
    }

    protected EventStore setStoreName(String name)
    {
        this.name = name;

        return this;
    }

    private void createOrOpenStore()
    {
        try
        {
            File segmentFile;

            for (var segment = 0; segment < segments; segment++)
            {
                segmentFile = new File(path + GlobalConstants.PATH_SEPARATOR + segment + ".segment");

                if (!segmentFile.exists())
                {
                    segmentFile.createNewFile();
                }

                writerChannel[segment] = FileChannel.open(segmentFile.toPath(), StandardOpenOption.WRITE, StandardOpenOption.READ);

                writer[segment] = writerChannel[segment].map(FileChannel.MapMode.READ_WRITE, 0, segmentSize);

                writingSegment = 0;

                writer[segment].putInt(0, Integer.MIN_VALUE); //EOF

                writingOffset[segment] += 4;

                readerChannel[segment] = FileChannel.open(segmentFile.toPath(), StandardOpenOption.READ);

                reader[segment] = readerChannel[segment].map(FileChannel.MapMode.READ_ONLY, 0, segmentSize);

                readingSegment = 0;

                readingOffset[segment] = 0;
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    protected void init(String readingBookmark, String writingBookmark) throws Exception
    {
        try
        {
            if (segments <= 0)
            {
                segments = 1;
            }

            writer = new MappedByteBuffer[segments];

            reader = new MappedByteBuffer[segments];

            readerChannel = new FileChannel[segments];

            writerChannel = new FileChannel[segments];

            writingOffset = new int[segments];

            readingOffset = new int[segments];

            if (name.trim().isEmpty())
            {
                throw new Exception("store name can not be blank...");
            }

            if (!CommonUtil.isNullOrEmpty(readingBookmark) && CommonUtil.getInteger(readingBookmark.split("_")[1]) > 0 && !CommonUtil.isNullOrEmpty(writingBookmark) && CommonUtil.getInteger(writingBookmark.split("_")[1]) > 0)
            {
                readingSegment = CommonUtil.getInteger(readingBookmark.split("_")[0]);

                var storeFile = new File(path + GlobalConstants.PATH_SEPARATOR + readingBookmark.split("_")[0] + ".segment");

                readerChannel[readingSegment] = FileChannel.open(storeFile.toPath(), StandardOpenOption.READ);

                reader[readingSegment] = readerChannel[readingSegment].map(FileChannel.MapMode.READ_ONLY, 0, segmentSize);

                readingOffset[readingSegment] = CommonUtil.getInteger(readingBookmark.split("_")[1]);

                writingSegment = CommonUtil.getInteger(writingBookmark.split("_")[0]);

                storeFile = new File(path + GlobalConstants.PATH_SEPARATOR + writingBookmark.split("_")[0] + ".segment");

                writerChannel[writingSegment] = FileChannel.open(storeFile.toPath(), StandardOpenOption.WRITE, StandardOpenOption.READ);

                writer[writingSegment] = writerChannel[writingSegment].map(FileChannel.MapMode.READ_WRITE, 0, segmentSize);

                writingOffset[writingSegment] = CommonUtil.getInteger(writingBookmark.split("_")[1]);
            }
            else
            {
                 createOrOpenStore();
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            throw new Exception(String.format("failed to open segment %s...", name));
        }
    }

    protected void init() throws Exception
    {
        init(null, null);
    }

    protected void load() throws Exception
    {
        try
        {
            var valid = false;

            var lockFile = new File(path + GlobalConstants.PATH_SEPARATOR + "lock");

            var bookmarks = new File(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

            if (bookmarks.exists() && !lockFile.exists())
            {
                var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(path + GlobalConstants.PATH_SEPARATOR + "bookmarks");

                if (buffer != null && buffer.length() > 0)
                {
                    valid = true;

                    var tokens = CommonUtil.getString(buffer).split(VALUE_SEPARATOR_WITH_ESCAPE);

                    init(tokens[0], tokens[1]);

                    LOGGER.debug(String.format("initialize event store %s...", name));
                }
            }

            if (!lockFile.exists())
            {
                lockFile.createNewFile();
            }

            if (!valid)
            {
                init();

                save();

                LOGGER.debug(String.format("initialize event store %s...", name));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void rolloverReadingSegment()
    {
        try
        {
            reader[readingSegment].clear();

            readerChannel[readingSegment].close();

            readingSegment += 1;

            if (readingSegment == segments)
            {
                readingSegment = 0;
            }

            LOGGER.debug(String.format("rollover reading segment %s...", name));

            readingOffset[readingSegment] = 0;
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

    }

    private byte[] readBytes()
    {
        byte[] bytes = null;

        var length = reader[readingSegment].getInt(readingOffset[readingSegment]);

        if (length > 0)
        {
            readingOffset[readingSegment] += 4;

            bytes = new byte[length];

            reader[readingSegment].get(readingOffset[readingSegment], bytes, 0, length);

            readingOffset[readingSegment] += length;

            pendingEvents[readingSegment] -= 1;
        }

        return bytes;
    }

    protected String getReadingBookmark()
    {
        return readingSegment + "_" + readingOffset[readingSegment];
    }

    protected String getWritingBookmark()
    {
        return writingSegment + "_" + writingOffset[writingSegment];
    }

    protected int getPendingEvents()
    {
        return Arrays.stream(this.pendingEvents).sum();
    }

    protected int getDroppedEvents()
    {
        return Arrays.stream(this.droppedEvents).sum();
    }


    protected void save()
    {
        Bootstrap.vertx().fileSystem().writeFileBlocking(path + PATH_SEPARATOR +  "bookmarks", Buffer.buffer(getReadingBookmark() + GlobalConstants.VALUE_SEPARATOR + getWritingBookmark()));
    }


    protected void close() throws Exception
    {
        for (int segment = 0; segment < segments; segment++)
        {
            readerChannel[segment].close();

            writerChannel[segment].close();
        }


        if (new File(path + GlobalConstants.PATH_SEPARATOR + "lock").exists())
        {
            Bootstrap.vertx().fileSystem().deleteBlocking(path + GlobalConstants.PATH_SEPARATOR + "lock");
        }
    }
}


