package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.*;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.*;

import static com.mindarray.GlobalConstants.ENV_TEST;
import static com.mindarray.GlobalConstants.MOTADATA_DB;
import static com.mindarray.db.DBConstants.BATCH_FILE;
import static com.mindarray.eventbus.EventBusConstants.*;

public class MetricDatastoreManager extends AbstractVerticle
{
    private final Logger LOGGER;
    private final TreeSet<String> eventFiles = new TreeSet<>();
    private final Map<String, Integer> eventFileOffset = new TreeMap<>();
    private final Map<String, String> deployedRouters = new HashMap<>();
    private final Map<String, Long> eventFileReaderTimer = new HashMap<>();
    private final String eventType;
    private final String clazz;
    private final int eventRouters;
    private String storeDirectory;
    private final boolean blocking;
    private JsonObject metricColumns;
    private boolean metricColumnMapperUpdated = false;

    public MetricDatastoreManager(String eventType, int eventRouters, String clazz,boolean blocking)
    {
        this.blocking = blocking;

        this.eventType = eventType;

        this.clazz = clazz;

        this.eventRouters = eventRouters >= 0 ? eventRouters : 1;

        this.LOGGER = new Logger(MetricDatastoreManager.class, MOTADATA_DB, String.format("Metric Data Store Manager:(%s)", eventType));
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var futures = new ArrayList<Future>();

        metricColumns = new JsonObject();

        loadColumns(metricColumns, DBConstants.METRIC_COLUMNS);

        storeDirectory = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.APP_EVENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.replace(eventType);

        for (var eventRouter = 0; eventRouter < this.eventRouters; eventRouter++)
        {
            load(eventRouter);

            var future = Promise.<Void>promise();

            var router = eventType + GlobalConstants.DOT_SEPARATOR + eventRouter;

            futures.add(future.future());

            if (blocking)
            {
                vertx.deployVerticle(clazz, new DeploymentOptions().setConfig(new JsonObject().put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router)).put(EVENT_TYPE, router)).setWorker(true).setWorkerPoolSize(1).setWorkerPoolName("wp." + router), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_CREATE), message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });

            }

            else
            {
                vertx.deployVerticle(clazz, new DeploymentOptions()
                        .setConfig(new JsonObject()
                                .put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router))
                                .put(EVENT_TYPE, router)), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_CREATE), message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
        }

        vertx.setPeriodic(10000, timerHandler ->
        {
            try
            {
                if (metricColumnMapperUpdated)
                {
                    metricColumnMapperUpdated = false;

                    vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + DBConstants.METRIC_COLUMNS,
                            Buffer.buffer(CodecUtil.compress(metricColumns.encode().getBytes())));
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE, message ->
        {
            try
            {
                var event = message.body();

                if (event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_METRIC_COLUMN.name()))
                {
                    update(metricColumns, event.getString(DBConstants.MAPPER).split(GlobalConstants.COLUMN_SEPARATOR, -1), true);

                    metricColumnMapperUpdated = true;
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_METRIC_COLUMN_MAPPER_QUERY, message ->
        {
            try
            {
                message.reply(new JsonObject().put(DBConstants.METRIC_COLUMNS, metricColumns));
            }
            catch (Exception exception)
            {
                message.fail(GlobalConstants.NOT_AVAILABLE, exception.getMessage());

                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        CompositeFuture.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                var requestTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_REQUEST);

                var readTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_READ);

                var removeTopic = eventType.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_REMOVE);

                vertx.setPeriodic(120 * 1000, handler -> clear(removeTopic));

                vertx.eventBus().<JsonObject>localConsumer(requestTopic, message ->
                {
                    try
                    {
                        LOGGER.trace("db metric store write request received");

                        var totalBytes = 0L;

                        var futurePromise = Promise.<Void>promise();

                        var requests = new ArrayList<JsonObject>();

                        var maxBufferBytes = message.body().getLong(DBConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES);

                        for (var eventFile : eventFiles)
                        {
                            var timestamp = CommonUtil.getLong(eventFile.split(GlobalConstants.DASH_SEPARATOR)[0]);

                            if((DateTimeUtil.currentSeconds() - timestamp) > 5 && totalBytes <= maxBufferBytes )
                            {
                                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + eventFile + ".dat");

                                if(file.exists() && file.length() > 0)
                                {
                                    var length = CommonUtil.getInteger(file.length());

                                    if (!eventFileOffset.containsKey(eventFile))
                                    {
                                        requests.add(new JsonObject()
                                                .put(EVENT_TYPE,readTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                .put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC)
                                                .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                        eventFileOffset.put(eventFile,length);

                                        eventFileReaderTimer.put(eventFile,System.currentTimeMillis());

                                        totalBytes += length;
                                    }
                                    else
                                    {
                                        var currentOffset = eventFileOffset.get(eventFile);

                                        if(currentOffset < length)
                                        {
                                            length = CommonUtil.getInteger(length - currentOffset);

                                            requests.add(new JsonObject().put(EVENT_TYPE,readTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                    .put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC)
                                                    .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                            eventFileOffset.put(eventFile, length + currentOffset);

                                            totalBytes += length;
                                        }
                                    }
                                }
                            }
                        }

                        if (!requests.isEmpty())
                        {
                            var requestFutures = new ArrayList<Future>();

                            LOGGER.debug(String.format("db store qualified %s files total bytes %s", requests.size(),totalBytes));

                            requests.forEach(item ->
                            {
                                var future = Promise.<Void>promise();

                                requestFutures.add(future.future());

                                Bootstrap.vertx().eventBus().<JsonObject>request(item.getString(EVENT_TYPE), item, handler -> future.complete());
                            });

                            CompositeFuture.join(requestFutures).onComplete(handler ->
                            {
                                LOGGER.debug(String.format("db store %s files received response", requests.size()));

                                requests.forEach(item->
                                {

                                    if(item.containsKey(EVENT_CONTEXT))
                                    {
                                        if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                                        {
                                            vertx.eventBus().send("test.datastore.metric", item);
                                        }

                                        vertx.eventBus().send(EVENT_PUBLICATION_INSERT_DATASTORE, item.put(EVENT_COPY_REQUIRED,false));

                                        LOGGER.debug(String.format("db store %s file send to datastore", item.getString(BATCH_FILE)));
                                    }
                                });

                                futurePromise.complete();
                            });
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).exceptionHandler(LOGGER::error);

                vertx.eventBus().<byte[]>localConsumer(eventType, message ->
                {
                    try
                    {
                        vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + (ByteUtil.readLongValue(message.body()) % eventRouters), message.body()); //send event to writer
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).exceptionHandler(LOGGER::error);

                promise.complete();
            }
            else
            {
                promise.fail(result.cause());
            }
        });
    }

    private void clear(String removeTopic)
    {
        try
        {
            for (var iterator = eventFiles.iterator(); iterator.hasNext();)
            {
                var entry = iterator.next();

                var timestamp = CommonUtil.getLong(entry.split(GlobalConstants.DASH_SEPARATOR)[0]);

                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + entry + ".dat");

                if(file.exists() && eventFileOffset.containsKey(entry) && eventFileOffset.get(entry) == file.length())
                {
                    eventFileOffset.remove(entry);

                    eventFileReaderTimer.remove(entry);

                    iterator.remove();

                    vertx.eventBus().send(removeTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters), entry);

                    LOGGER.debug(String.format("event db store %s file deleted because file reach point reach EOF", entry));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(int eventRouter)
    {
        try
        {
            var files = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + eventRouter).listFiles();

            if (files != null)
            {
                Arrays.stream(files).filter(file->file.getName().endsWith(".dat")).forEach(file-> eventFiles.add(file.getName().split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0]));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            var futures = new ArrayList<Future>();

            for (var deploymentId : deployedRouters.values())
            {
                var future = Promise.<Void>promise();

                futures.add(future.future());

                vertx.undeploy(deploymentId, handler -> future.complete());
            }

            CompositeFuture.join(futures).onComplete(handler -> promise.complete());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            if (!promise.future().isComplete())
            {
                promise.fail(exception);
            }
        }
    }

    private void loadColumns(JsonObject columns, String filter)
    {
        try
        {
            var file = new File(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + filter);

            if (file.exists())
            {
                var buffer = vertx.fileSystem().readFileBlocking(file.getPath());

                if (buffer != null && buffer.getBytes().length > 0)
                {
                    columns.mergeIn(new JsonObject(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes()))));

                    LOGGER.info(String.format("%s loaded from the backup file...", filter));
                }
            }

            else
            {
                vertx.fileSystem().createFileBlocking(file.getPath());
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void update(JsonObject columns, String[] tokens, boolean metric)
    {
        var column = tokens[DBConstants.MetricWriterOrdinal.COLUMN.ordinal()].toLowerCase();

        var garbageColumn = false;

        if (!columns.containsKey(column))
        {
            columns.put(column, new JsonObject());
        }

        var mapper = columns.getJsonObject(column);

        var plugins = mapper.getJsonArray(DBConstants.MAPPER_PLUGIN_IDS);

        if (plugins == null)
        {
            plugins = new JsonArray(new ArrayList<>(1));
        }

        if (!plugins.contains(CommonUtil.getInteger(tokens[1])))
        {
            mapper.put(DBConstants.MAPPER_PLUGIN_IDS, plugins.add(CommonUtil.getInteger(tokens[1])));
        }

        var dataCategories = mapper.getJsonArray(DBConstants.MAPPER_DATA_CATEGORIES);

        if (metric)
        {
            mapper.put(DBConstants.MAPPER_STATUS, tokens[3]);

            //#24371 add garbage column
            if (mapper.getString(DBConstants.MAPPER_STATUS).equalsIgnoreCase(GlobalConstants.NO) && (column.endsWith(".id") || column.endsWith(".uptime") || column.endsWith(".version") || column.endsWith(".state") ||
                    column.endsWith(".status") || column.endsWith(".creation.time.seconds") || column.endsWith(".uptime.sec") ||
                    column.endsWith(".uptime.seconds") || column.endsWith(".time.seconds") || column.endsWith(".started.time")))
            {
                garbageColumn = true;
            }
        }

        if (plugins.contains(DBConstants.PluginId.CORRELATED_METRIC.getName()))
        {
            mapper.put(DBConstants.MAPPER_CORRELATED, tokens[3]);
        }

        if (!metric && tokens.length > 4)
        {
            mapper.put(DBConstants.MAPPER_EVENT_CATEGORY, tokens[4]);
        }

        if (metric && tokens.length > 4)
        {
            mapper.put(DBConstants.MAPPER_DURATION, tokens[4]);
        }

        if (dataCategories == null)
        {
            dataCategories = new JsonArray(new ArrayList<>(1));
        }

        if (garbageColumn)
        {
            mapper.put(DBConstants.MAPPER_DATA_CATEGORIES, dataCategories.add(DBConstants.DataCategory.STRING.getName()));
        }
        else
        {
            if (!dataCategories.contains(CommonUtil.getInteger(tokens[0])))
            {
                mapper.put(DBConstants.MAPPER_DATA_CATEGORIES, dataCategories.add(CommonUtil.getInteger(tokens[0])));
            }
        }

        if (column.contains(GlobalConstants.INSTANCE_SEPARATOR))
        {
            //25286 Bug lowercase
            mapper.put(DBConstants.MAPPER_INSTANCE, column.split(GlobalConstants.INSTANCE_SEPARATOR)[0].toLowerCase());
        }

        if (mapper.containsKey(DBConstants.MAPPER_CORRELATED) && mapper.getString(DBConstants.MAPPER_CORRELATED).equalsIgnoreCase(GlobalConstants.YES))
        {
            mapper.put(DBConstants.MAPPER_GROUP, tokens[DBConstants.EventWriterOrdinal.GROUP.ordinal()]);
        }
    }

