package com.mindarray.ha;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.api.User;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.MappedByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.DB_QUERY;
import static com.mindarray.eventbus.EventBusConstants.*;

public class ConfigManager extends AbstractVerticle {
    private static final Logger LOGGER = new Logger(ConfigManager.class, GlobalConstants.MOTADATA_DB, "Config DB Manager");
    private String path;
    private byte[] bytes = new byte[8 * 1024];
    private final Map<String, Long> itemsByUUID = new HashMap<>(); //items by uuid store last read file
    private final Map<Long, FileChannel> eventFileReaderChannels = new TreeMap<>(); //store all files by time order (milliseconds)
    private final Map<Long, MappedByteBuffer> eventFileMappedByteBuffers = new TreeMap<>(); //store all files by time order (milliseconds)

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.OBSERVER.name()))
            {
                var storeDir = new File(CURRENT_DIR + PATH_SEPARATOR + EventBusConstants.EVENT_DIR + PATH_SEPARATOR
                        + EventBusConstants.replace(EventBusConstants.EVENT_DATASTORE_WRITE
                        + GlobalConstants.DOT_SEPARATOR + DBConstants.DatastoreCategory.CONFIG.getName()));

                path = storeDir.getPath();

                if (!storeDir.exists())
                {
                    storeDir.mkdirs();
                }

                load(storeDir);

                vertx.setPeriodic(120 * 1000, handler -> purge());

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_WRITE, event -> write(event.body())).exceptionHandler(LOGGER::error);

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_READ, event -> read(event.body())).exceptionHandler(LOGGER::error);
            }

            if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.APP.name()))
            {
                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_SYNC_FLUSH, message -> decodeEvent(message.body()));

                vertx.setPeriodic(MotadataConfigUtil.getConfigDBRequestTimer(), handler ->
                {
                    if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                    {
                        vertx.eventBus().send(EVENT_HA_MANAGER,
                                new JsonObject().put(EVENT_TYPE,EVENT_CONFIG_SYNC_READ)
                                        .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId())
                                        .put(DatastoreConstants.DATASTORE_WRITER_MAX_BUFFER_BYTES,1048576L));
                    }
                });
            }

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(File storeDirectory)
    {
        try
        {
            var files = new File(storeDirectory.getPath()).listFiles();

            if (files != null)
            {
                for (var file : files)
                {
                    if (file.getName().equalsIgnoreCase("bookmarks"))
                    {
                        var timestamp = CommonUtil.getLong(file.getName().trim());

                        var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp);

                        eventFileReaderChannels.put(timestamp,FileChannel.open(eventFile.toPath(), StandardOpenOption.READ));

                        eventFileMappedByteBuffers.put(timestamp,eventFileReaderChannels.get(timestamp).map(FileChannel.MapMode.READ_ONLY, 0, eventFile.length()));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void write(JsonObject context)
    {
        try
        {
            var buffer = context.getBinary(EVENT_CONTEXT);

            var timestamp = ByteUtil.readLongValue(buffer);

            BufferedOutputStream bufferedOutputStream;

            try (var fileOutputStream = new FileOutputStream(path + GlobalConstants.PATH_SEPARATOR + timestamp, false))
            {
                bufferedOutputStream = new BufferedOutputStream(fileOutputStream, this.bytes.length);

                bufferedOutputStream.write(buffer, 0, buffer.length);

                bufferedOutputStream.flush();

                bufferedOutputStream.close();

                var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp);

                eventFileReaderChannels.put(timestamp,FileChannel.open(eventFile.toPath(), StandardOpenOption.READ));

                eventFileMappedByteBuffers.put(timestamp,eventFileReaderChannels.get(timestamp).map(FileChannel.MapMode.READ_ONLY, 0, eventFile.length()));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void read(JsonObject context)
    {
        try
        {
            var uuid = context.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID);

            var timestamp = itemsByUUID.get(uuid);

            for (var iterator = eventFileReaderChannels.entrySet().iterator(); iterator.hasNext();)
            {
                var entry = iterator.next();

                if(entry.getKey() > timestamp)
                {
                    var eventFile = new File(path + GlobalConstants.PATH_SEPARATOR + timestamp);

                    var bufferBytes = new byte[CommonUtil.getInteger(eventFile.length())];

                    eventFileMappedByteBuffers.get(timestamp).get(0, bufferBytes, 0, bufferBytes.length);

                    vertx.eventBus().send(EVENT_PUBLICATION,new JsonObject().put(EVENT_CONTEXT,bufferBytes)
                                    .put(EVENT_TOPIC,REMOTE_EVENT_PROCESSOR_TOPIC)
                            .put(EVENT_COPY_REQUIRED,false).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid)
                            .put(EVENT_TYPE, EventBusConstants.EVENT_CONFIG_SYNC_FLUSH));

                    itemsByUUID.put(uuid,timestamp);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void decodeEvent(JsonObject event)
    {
        var offset = 0;

        var byteBuffer = Buffer.buffer(event.getBinary(EVENT_CONTEXT));

        while(offset < byteBuffer.length())
        {
            try
            {
                var rowLength = byteBuffer.getIntLE(offset); // read row length

                if(rowLength > 0)
                {
                    offset = offset + 4; //skip row length bytes

                    var bytes = Buffer.buffer(CodecUtil.toBytes(byteBuffer.getBytes(offset, offset + rowLength))); // read row bytes snappy compressed

                    updateConfig(new JsonObject(new String(bytes.getBytes(12,12 + bytes.getIntLE(8))))); // decode row bytes

                    offset = offset + rowLength; //skip row buffer length bytes
                }
                else
                {
                    LOGGER.warn(String.format("ignore batch decode in db metric store file %s = %s / %s / %s = ", event.getString(EVENT_FILE),offset,rowLength,byteBuffer.length()));

