import static com.mindarray.GlobalConstants.MOTADATA_DATASTORE;
import static com.mindarray.eventbus.EventBusConstants.*;

public class MetricDatastoreManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(MetricDatastoreManager.class, MOTADATA_DATASTORE, "Metric Datastore Manager");

    private EventDatastoreEngine eventEngine;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        eventEngine = new EventDatastoreEngine().setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                .setPersistEventOffset(true).setPause(true).setLogger(LOGGER).setEventHandler(this::send).start(vertx, promise);

        promise.complete();
    }

    private void send(JsonObject event)
    {
        try
        {
            // TODO : if database down ??

            for (var type:GlobalConstants.InstallationMode.values())
            {
                var id = RemoteEventProcessorConfigStore.getStore().getItemByMode(type);

                if (id != null)
                {
                    var item = RemoteEventProcessorConfigStore.getStore().getItem(id);

                    vertx.eventBus().send(EVENT_PUBLICATION_DATASTORE_WRITE, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)).put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC));

                    LOGGER.trace(String.format("event sent to datastore %s ",item.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }


    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            eventEngine.stop(vertx, promise);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

}

