    /**
     * Method to remove fields which are not required in configuration context
     */
    public static void removeGarbageFields(JsonObject object)
    {
        object.put(CONFIG_OBJECT_ID, object.getLong(ID)); // Will be used in widget rendering and health status in used count

        APIUtil.removeDefaultParameters(object);

        object.remove(AIOpsObject.OBJECT_CONTEXT);

        object.remove(AIOpsObject.OBJECT_BUSINESS_HOUR_PROFILE);

        object.remove(Discovery.DISCOVERY_CONFIG_MANAGEMENT_STATUS);

        object.remove(Discovery.DISCOVERY_CREDENTIAL_PROFILES);

        object.remove(AIOpsObject.OBJECT_ID);
    }

    /**
     * Method will enrich the config request context by attaching credential profile, config context
     * and qualified config plugin
     *
     * @param event           Event
     * @param configOperation Config Request Type
     */
    protected static void enrich(JsonObject event, ConfigOperation configOperation)
    {
        if (configOperation.equals(ConfigOperation.DISCOVERY))
        {
            var credentialProfiles = event.containsKey(Configuration.CONFIG_CREDENTIAL_PROFILE) ? new JsonArray().add(CredentialProfileConfigStore.getStore().getItem(event.getLong(Configuration.CONFIG_CREDENTIAL_PROFILE))) : NMSConstants.filterCredentialProfiles(event, true);

            if (credentialProfiles != null && !credentialProfiles.isEmpty())
            {
                for (var index = 0; index < credentialProfiles.size(); index++)
                {
                    var credential = credentialProfiles.getJsonObject(index);

                    credential.mergeIn(credential.getJsonObject(CredentialProfile.CREDENTIAL_PROFILE_CONTEXT))
                            .remove(CredentialProfile.CREDENTIAL_PROFILE_CONTEXT);
                }

                event.put(Discovery.DISCOVERY_CREDENTIAL_PROFILES, credentialProfiles);

                // Considering first profile's protocol to qualify plugin at go engine
                event.put(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL, credentialProfiles.getJsonObject(0).getString(CredentialProfile.CREDENTIAL_PROFILE_PROTOCOL));
            }
            else
            {
                // When no profile get qualified
                event.remove(Discovery.DISCOVERY_CREDENTIAL_PROFILES);
            }
        }
        else
        {
            var credentialProfile = CredentialProfileConfigStore.getStore().getItem(event.getLong(Configuration.CONFIG_CREDENTIAL_PROFILE));

            if (credentialProfile != null)
            {
                credentialProfile.remove(GlobalConstants.ID);

                credentialProfile.mergeIn(credentialProfile.getJsonObject(CredentialProfile.CREDENTIAL_PROFILE_CONTEXT))
                        .remove(CredentialProfile.CREDENTIAL_PROFILE_CONTEXT);

                event.mergeIn(credentialProfile);
            }
        }

        event.mergeIn(event.getJsonObject(Configuration.CONFIG_CONTEXT)).remove(Configuration.CONFIG_CONTEXT);
    }

    /**
     * Method will qualify the object for which we are going to provide support for the configuration management
     * MOTADATA-1900 - Load Balancer in NCM
     * - Added support for load balancer, wireless controller and snmp device type in NCM 
     * @param type Object Type
     * @return Object category
     */
    public static NMSConstants.Category qualify(NMSConstants.Type type)
    {
        return switch (type)
        {
            case SWITCH, ROUTER, FIREWALL, LOAD_BALANCER, SNMP_DEVICE, WIRELESS_CONTROLLER -> NMSConstants.Category.NETWORK;

            default -> null;
        };
    }

    /**
     * Method will check the template using mapped catalog
     * If, template not found by catalog then, it will try using vendor
     *
     * @param event Event
     * @return List of templates
     */
    protected static JsonArray qualifyTemplate(JsonObject event)
    {
        var templates = new JsonArray();

        if (event.containsKey(AIOpsObject.OBJECT_SNMP_DEVICE_CATALOG))
        {
            templates = ConfigTemplateConfigStore.getStore().getConfigTemplates(event.getLong(AIOpsObject.OBJECT_SNMP_DEVICE_CATALOG));

            if (templates == null || templates.isEmpty())
            {
                LOGGER.debug("No template qualified by catalog");

                if (event.containsKey(AIOpsObject.OBJECT_VENDOR))
                {
                    // Qualify all templates by vendor
                    templates = ConfigTemplateConfigStore.getStore().getItemsByValue(ConfigTemplate.CONFIG_TEMPLATE_VENDOR, event.getString(AIOpsObject.OBJECT_VENDOR));

                    LOGGER.debug(String.format("No. of qualified templates are : %s", templates != null ? templates.size() : 0));
                }
            }
        }

        return templates;
    }

    protected static void deleteBackupFile(JsonObject event)
    {
        if (event.containsKey(RESULT))
        {
            var result = event.getJsonObject(RESULT);

            for (var type : ConfigConstants.ConfigBackupType.values())
            {
                if (result.containsKey(type.getName()))
                {
                    LOGGER.info("Deleting file :: " + result.getString(type.getName()));

                    var file = new File(ConfigConstants.CONFIG_MANAGEMENT_DEFAULT_DIR + PATH_SEPARATOR + result.getString(type.getName()));

                    // File exists when protocol is FTP, TFTP or SFTP
                    if (file.exists())
                    {
                        FileUtils.deleteQuietly(file);
                    }

                    // Need to remove context in-case of No protocol if exists
                    result.remove(type.getName() + ConfigConstants.BACKUP_FILE_CONTENT);
                }
            }
        }
    }

