import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(VertxExtension.class)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(300 * 1000)
@EnabledIfSystemProperty(named = "test.mode", matches = "^APP|^PRIMARY$")
public class TestAgentUpgradeManager
{
    private static final Logger LOGGER = new Logger(TestAgentUpgradeManager.class, GlobalConstants.MOTADATA_APP_MANAGER, "Test Agent Manager Upgrade");

    private static final Vertx VERTX = TestUtil.vertx();

    private static MessageConsumer<JsonObject> messageConsumer;

    private static MessageConsumer<JsonObject> consumer;

    private static MessageConsumer<JsonObject> completionConsumer;

    private final int TOTAL_AGENTS = 200;

    private static final JsonArray entities = new JsonArray();

    private static final AtomicInteger completed = new AtomicInteger();

    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {
        try
        {
            var port = MotadataConfigUtil.getHTTPServerPort(BootstrapType.APP.name());

            consumer = VERTX.eventBus().localConsumer(EVENT_PUBLICATION_MOTADATA_MANAGER, message ->
            {
                try
                {
                    var event = message.body();

                    LOGGER.trace(event);

                    if (event.containsKey(EVENT_TYPE) && (event.getString(EVENT_TYPE).equalsIgnoreCase(EVENT_AGENT_UPGRADE) || event.getString(EVENT_TYPE).equalsIgnoreCase(EVENT_MANAGER_UPGRADE)))
                    {
                        VERTX.eventBus().publish(EVENT_MANAGER_RESPONSE_PROCESSOR, event.put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()).put(MESSAGE, "Stopping Motadata service ....").put(STATUS, STATUS_SUCCEED).put(PROGRESS, 5.0));

                        VERTX.setTimer(TimeUnit.SECONDS.toMillis(2), timer -> VERTX.eventBus().publish(EVENT_MANAGER_RESPONSE_PROCESSOR, event.put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()).put(MESSAGE, "Fetching files ...").put(PROGRESS, 20.0)));

                        VERTX.setTimer(TimeUnit.SECONDS.toMillis(5), timer -> VERTX.eventBus().publish(EVENT_MANAGER_RESPONSE_PROCESSOR, event.put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()).put(MESSAGE, "Starting Motadata service ...").put(PROGRESS, 90.0)));

                        VERTX.setTimer(TimeUnit.SECONDS.toMillis(8),id -> VERTX.eventBus().publish(EVENT_MANAGER_RESPONSE_PROCESSOR, event.put(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()).put(MESSAGE, "Motadata service started successfully! ....").put(PROGRESS, 100.0).put(PORT, port)));
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            testContext.completeNow();
        }
        catch (Exception exception)
        {
            testContext.failNow(exception.getMessage());
        }
    }

    @AfterAll
    static void afterAll(VertxTestContext testContext)
    {
        TestAPIUtil.deleteAll(AGENT_API_ENDPOINT, new JsonObject().put(APIConstants.REQUEST_PARAM_IDS, entities), response ->
        {
            if (response.succeeded())
            {
                var result = response.result().bodyAsJsonObject();

                testContext.verify(()->
                {
                    assertEquals(HttpStatus.SC_OK, result.getInteger(RESPONSE_CODE));

                    assertTrue(result.getString(GlobalConstants.STATUS).equalsIgnoreCase(GlobalConstants.STATUS_SUCCEED));

                    assertTrue(result.getString(GlobalConstants.MESSAGE).equalsIgnoreCase("Agent deleted successfully"));

                    if (completionConsumer != null)
                    {
                        completionConsumer.unregister();
                    }

                    if (consumer != null)
                    {
                        consumer.unregister();
                    }

                    if (messageConsumer != null)
                    {
                        messageConsumer.unregister(handler -> testContext.completeNow());
                    }
                    else
                    {
                        testContext.completeNow();
                    }
                });
            }
            else
            {
                LOGGER.warn(response.cause().getMessage());
            }
        });
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    void testRegisterAgents(VertxTestContext testContext, TestInfo testInfo)
    {
        LOGGER.info(String.format("running %s", testInfo.getTestMethod().get().getName()));

        var cipherUtil = new CipherUtil();

        try (var producer = Bootstrap.zcontext().socket(SocketType.PUSH))
        {
            producer.connect("tcp://*:" + CommonUtil.getEventReceiverPort(MotadataConfigUtil.getEventAppReceiverProtocols().get(0)));

            for (var index = 0; index < TOTAL_AGENTS; index++)
            {
                var agent = new JsonObject().put("object.ip", String.format("10.20.41.%s", (1 + index)))
                        .put("agent.version", "8.1.0")
                        .put("agent.os.name", "linux")
                        .put("objects", new JsonArray().add(String.format("10.20.41.%s", (1 + index))))
                        .put("agent.id", "AGENT-YASH" + index)
                        .put("event.type", "agent.registration")
                        .put("object.host", "agent-test-" + (1+ index))
                        .put("agent.configs", new JsonObject().put("agent", new JsonObject()
                                .put("agent.id", "AGENT-YASH" + index)
                                .put("agent.deactivation.status", "no")
                                .put("metric.agent.status", "no")
                                .put("agent.state", "ENABLE")));

                producer.send(Buffer.buffer().appendShortLE(CommonUtil.getShort(EventBusConstants.AGENT_TOPIC.length())).appendString(EventBusConstants.AGENT_TOPIC).appendBytes(cipherUtil.encrypt(CodecUtil.compress(agent.encode()))).getBytes());
            }

            testContext.completeNow();
        }
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(2)
    void testBulkAgentUpgrade(VertxTestContext testContext, TestInfo testInfo)
    {
        LOGGER.info(String.format("running %s", testInfo.getTestMethod().get().getName()));

        TestUtil.createZipFile(new String[]{"VERSION"}, CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + "agent-artifact.zip", "linux", "10.10.11");

        assertEventUpgradeResult(testContext, "agent-artifact.zip", 10, true);
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(3)
    void testBulkManagerUpgrade(VertxTestContext testContext, TestInfo testInfo)
    {
        LOGGER.info(String.format("running %s", testInfo.getTestMethod().get().getName()));

        TestUtil.createZipFile(new String[]{"VERSION", "upgrade.me"}, CURRENT_DIR + PATH_SEPARATOR + "uploads" + PATH_SEPARATOR + "manager-artifact.zip", "linux", "10.10.11");

        assertEventUpgradeResult(testContext, "manager-artifact.zip",2, false);
    }

    private void assertEventUpgradeResult(VertxTestContext testContext, String fileName,  int initialWaitingSeconds, boolean clear)
    {
        messageConsumer = VERTX.eventBus().localConsumer(EVENT_UI, message ->
        {
            try
            {
                if (message.body().getString(EVENT_TYPE) != null && message.body().getString(EVENT_TYPE).equalsIgnoreCase(UI_NOTIFICATION_AGENT_UPGRADE_PROGRESS))
                {
                    var context = CodecUtil.toJSONObject(message.body().getBinary(EventBusConstants.EVENT_CONTEXT));

                    LOGGER.debug(String.format("manager upgrade response : %s", context.encodePrettily()));

                    testContext.verify(() ->
                    {
                        assertNotNull(context.getString(MotadataApp.ARTIFACT_UPGRADE_STATUS));

                        assertTrue(context.containsKey(MESSAGE));

                        var id = CommonUtil.getString(context.getLong(ID));

                        Assertions.assertNotNull(id);

                        var state = context.getString(MotadataApp.ARTIFACT_UPGRADE_STATUS).split(SPACE_SEPARATOR)[2].toLowerCase();

                        Assertions.assertTrue(state.equalsIgnoreCase("requested") || state.equalsIgnoreCase("queued") || state.equalsIgnoreCase("initiated") || state.equalsIgnoreCase("successful"));

                        if (completed.get() == TOTAL_AGENTS)
                        {
                            completed.set(0);

                            if (clear)
                            {
                                entities.clear();
                            }

                            messageConsumer.unregister(handler -> testContext.completeNow());
                        }
                    });
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        completionConsumer = VERTX.eventBus().localConsumer(EVENT_UPGRADE_COMPLETE, message -> completed.incrementAndGet());

        VERTX.setTimer(TimeUnit.SECONDS.toMillis(initialWaitingSeconds), timer ->
        {
            for (var index = 0; index < TOTAL_AGENTS; index++)
            {
                try
                {
                    var id = AgentConfigStore.getStore().getAgentId("AGENT-YASH" + index);

                    Assertions.assertNotNull(id);

                    AgentCacheStore.getStore().updateItem(id, AgentCacheStore.getStore().getItem(id).put(MotadataAppManager.HEARTBEAT_STATE, STATE_RUNNING));

                    entities.add(id);
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            }

            Assertions.assertEquals(TOTAL_AGENTS, entities.size());

            VERTX.eventBus().send(UI_ACTION_AGENT_UPGRADE, new JsonObject().put(SESSION_ID, TestUtil.getSessionId()).put(EVENT_TYPE, EVENT_AGENT_UPGRADE).put(PATCH_ARTIFACT_FILE, fileName).put(ENTITIES, entities).put(MotadataApp.ARTIFACT_TYPE, APIConstants.Entity.AGENT.getName()).put(User.USER_NAME, DEFAULT_USER));
        });
    }
}

