public class BootstrapSecondary
{
    private static final Logger LOGGER = new Logger(BootstrapSecondary.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Secondary");

    public void start()
    {
        try
        {
            // TODO :- as of now temporarily making below condition true.
            if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) || PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
            {
                DatastoreConstants.loadConfigs();

                Bootstrap.logSystemConfig();

                ProcessUtil.setProcessors();

                EventBusConstants.setRemoteEventProcessorRegistrationId();

                startEngine(new ConfigDBServiceProvider(), ConfigDBServiceProvider.class.getSimpleName(), null)
                        .compose(future -> startEngine(new RemoteEventForwarder(MotadataConfigUtil.getMotadataObserverEventSubscriberPort(),MotadataConfigUtil.getRemoteEventObserverSubscriber()), RemoteEventForwarder.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), null))
                        .compose(future -> startEngine(new RemoteEventSubscriber(MotadataConfigUtil.getMotadataObserverEventPublisherPort(),MotadataConfigUtil.getRemoteEventObserverPublisher()), RemoteEventSubscriber.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventPublisherPort(), null))
                        .onComplete(resultHandler ->
                        {
                            if (resultHandler.succeeded())
                            {
                                ConfigDBInitializer.init().onComplete(configHandler ->
                                {
                                    if (configHandler.succeeded())
                                    {
                                        var asyncPromise = Promise.promise();

                                        // init all stores...
                                        Bootstrap.initStores().onComplete(response ->
                                        {
                                            if (response.succeeded())
                                            {
                                                LOGGER.info("all config/cache stores loaded successfully...");

                                                asyncPromise.complete();
                                            }
                                            else
                                            {
                                                asyncPromise.fail(response.cause());
                                            }
                                        });

                                        asyncPromise.future().onComplete(handler ->
                                        {
                                            if (handler.succeeded())
                                            {
                                                var futures = new ArrayList<Future>();

                                                var forwarderPort = CommonUtil.getEventPublisherPort();

                                                for (var index = 0; index < MotadataConfigUtil.getEventPublishers(); index++)
                                                {
                                                    var promise = Promise.promise();

                                                    futures.add(promise.future());

                                                    Bootstrap.startEngine(new RemoteEventForwarder(forwarderPort + index), RemoteEventForwarder.class.getSimpleName() + " " + (forwarderPort + index), null).onComplete(asyncResult ->
                                                    {
                                                        if (asyncResult.succeeded())
                                                        {
                                                            promise.complete();
                                                        }
                                                        else
                                                        {
                                                            promise.fail(asyncResult.cause());
                                                        }
                                                    });
                                                }

                                                CompositeFuture.join(futures).onComplete(asyncResult ->
                                                {
                                                    if (asyncResult.succeeded())
                                                    {
                                                        var asyncResults = new ArrayList<Future>();

                                                        var subscriberPort = CommonUtil.getEventSubscriberPort();

                                                        for (var index = 0; index < MotadataConfigUtil.getEventSubscribers(); index++)
                                                        {
                                                            var promise = Promise.promise();

                                                            asyncResults.add(promise.future());

                                                            Bootstrap.startEngine(new RemoteEventSubscriber(subscriberPort + index), RemoteEventSubscriber.class.getSimpleName() + " " + (subscriberPort + index), null).onComplete(voidAsyncResult ->
                                                            {
                                                                if (voidAsyncResult.succeeded())
                                                                {
                                                                    promise.complete();
                                                                }
                                                                else
                                                                {
                                                                    promise.fail(voidAsyncResult.cause());
                                                                }
                                                            });
                                                        }

                                                        CompositeFuture.join(asyncResults).onComplete(asyncResultHandler ->
                                                        {
                                                            startEngine(new ConfigDBDatastoreManager(), ConfigDBDatastoreManager.class.getCanonicalName(), null)
                                                                    .compose(future -> startEngine(new RemoteEventChangeNotificationHandler(), RemoteEventChangeNotificationHandler.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new DiscoveryEngine(), DiscoveryEngine.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new TopologyEngine(), TopologyEngine.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new RediscoverEngine(), RediscoverEngine.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new PluginEngine(), PluginEngine.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new MetricPoller(), MetricPoller.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new AutoScaler(), AutoScaler.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new PluginEngineResponseProcessor(), PluginEngineResponseProcessor.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new HealthUtil(), HealthUtil.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new LocalEventRouter(EventBusConstants.EVENT_LOG, EventBusConstants.EVENT_SOURCE, MotadataConfigUtil.getLogParsers(), LogParser.class.getCanonicalName(), true), LogParser.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new RemoteSessionManager(), RemoteSessionManager.class.getSimpleName(), null))
                                                                    .compose(future -> startEngine(new DatastoreManager(), DatastoreManager.class.getSimpleName(), null))
                                                                    .onComplete(result ->
                                                                    {
                                                                        try
                                                                        {
                                                                            if (result.succeeded())
                                                                            {
                                                                                Bootstrap.configDBService().getOne(DBConstants.COLLECTION_SYSTEM,
                                                                                        asyncResponse ->
                                                                                        {
                                                                                            if (asyncResponse.succeeded())
                                                                                            {
                                                                                                LicenseUtil.init(!asyncResponse.result().containsKey(INSTALLATION_DATE)).onComplete(response ->
                                                                                                {
                                                                                                    if (response.succeeded())
                                                                                                    {
                                                                                                        try
                                                                                                        {
                                                                                                            LOGGER.info("license verified successfully...");

                                                                                                            LicenseUtil.load(response.result());

                                                                                                            EventBusConstants.register(new CipherUtil());

                                                                                                            Bootstrap.vertx().eventBus().send(EVENT_REMOTE, new JsonObject()
                                                                                                                    .put(EVENT_TYPE, EVENT_ATTACH_DETACH_VIP)
                                                                                                                    .put(OPERATION_TYPE,ATTACH_VIP)
                                                                                                                    .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC));

                                                                                                            LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, MotadataConfigUtil.getInstallationMode()));
                                                                                                        }
                                                                                                        catch (Exception exception)
                                                                                                        {
                                                                                                            stop(exception);
                                                                                                        }
                                                                                                    }
                                                                                                    else
                                                                                                    {
                                                                                                        stop(response.cause());
                                                                                                    }
                                                                                                });
                                                                                            }
                                                                                            else
                                                                                            {
                                                                                                LOGGER.fatal("something went wrong with config db service..");

                                                                                                LOGGER.info("stopping config db service...");

                                                                                                stop(asyncResponse.cause());
                                                                                            }
                                                                                        });

                                                                            }
                                                                            else
                                                                            {
                                                                                LOGGER.error(result.cause());

                                                                                stop(result.cause());
                                                                            }
                                                                        }
                                                                        catch (Exception exception)
                                                                        {
                                                                            LOGGER.error(exception);
                                                                        }
                                                                    });
                                                        });

                                                    }
                                                    else
                                                    {
                                                        LOGGER.error(asyncResult.cause());

