package com.mindarray.api;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.TestAPIConstants;
import com.mindarray.TestAPIUtil;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.store.FlowSamplingRateConfigStore;
import io.github.artsok.RepeatedIfExceptionsTest;
import io.vertx.core.json.JsonObject;
import io.vertx.junit5.Timeout;
import io.vertx.junit5.VertxExtension;
import io.vertx.junit5.VertxTestContext;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.junit.jupiter.api.extension.ExtendWith;

import java.util.concurrent.TimeUnit;

@ExtendWith(VertxExtension.class)
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(70 * 1000)
@EnabledIfSystemProperty(named = "system.bootstrap.type", matches = "APP")
public class TestFlowSamplingRate
{
    private static final String IP = "1.2.3.4";

    @BeforeAll
    static void beforeAll(VertxTestContext testContext)
    {
        Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_CHANGE_LOCAL_NOTIFICATION,
                new JsonObject().put(EventBusConstants.EVENT_SOURCE, IP)
                        .put(EventBusConstants.EVENT, EventBusConstants.EVENT_FLOW)
                        .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.ADD_EVENT_SOURCE)
                        .put(GlobalConstants.PLUGIN_ID, DBConstants.PluginId.FLOW_EVENT.getName()));

        testContext.completeNow();
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    public void testSaveFlowSamplingRate(VertxTestContext testContext) throws InterruptedException
    {
        var context = new JsonObject("{\"params\":[{\"interface\":\"24\",\"interface.name\":\"EO0/0\",\"interface.description\":\"EOBC0/0\",\"interface.alias\":\"\",\"interface.speed.bytes.per.sec\":12500000,\"interface.sampling.rate\":10}]}");

        TestAPIUtil.post(TestAPIConstants.FLOW_SAMPLING_RATES + "/" + IP, context, testContext.succeeding(response -> testContext.verify(() ->
        {

            Assertions.assertEquals(200, response.statusCode());

            Assertions.assertNotNull(FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP));

            Assertions.assertEquals(10, FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP).getJsonObject(NMSConstants.OBJECTS).getJsonObject("24").getInteger(NMSConstants.INTERFACE_SAMPLING_RATE));

            testContext.completeNow();

        })));

        Assertions.assertTrue(testContext.awaitCompletion(10, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(2)
    public void testUpdateFlowSamplingRate1(VertxTestContext testContext) throws InterruptedException
    {
        var context = new JsonObject("{\"params\":[{\"interface\":\"25\",\"interface.name\":\"EO0/1\",\"interface.description\":\"EOBC0/1\",\"interface.alias\":\"\",\"interface.speed.bytes.per.sec\":12500000,\"interface.sampling.rate\":20}]}");

        TestAPIUtil.post(TestAPIConstants.FLOW_SAMPLING_RATES + "/" + IP, context, testContext.succeeding(response -> testContext.verify(() ->
        {

            Assertions.assertEquals(200, response.statusCode());

            Assertions.assertNotNull(FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP));

            Assertions.assertEquals(20, FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP).getJsonObject(NMSConstants.OBJECTS).getJsonObject("25").getInteger(NMSConstants.INTERFACE_SAMPLING_RATE));

            testContext.completeNow();
        })));

        Assertions.assertTrue(testContext.awaitCompletion(10, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(3)
    public void testUpdateFlowSamplingRate2(VertxTestContext testContext) throws InterruptedException
    {
        var context = new JsonObject("{\"params\":[{\"interface\":\"24\",\"interface.name\":\"EO0/0\",\"interface.description\":\"EOBC0/0\",\"interface.alias\":\"\",\"interface.speed.bytes.per.sec\":12500000,\"interface.sampling.rate\":30}]}");

        TestAPIUtil.post(TestAPIConstants.FLOW_SAMPLING_RATES + "/" + IP, context, testContext.succeeding(response -> testContext.verify(() ->
        {

            Assertions.assertEquals(200, response.statusCode());

            Assertions.assertNotNull(FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP));

            Assertions.assertEquals(30, FlowSamplingRateConfigStore.getStore().getItemByValue(EventBusConstants.EVENT_SOURCE, IP).getJsonObject(NMSConstants.OBJECTS).getJsonObject("24").getInteger(NMSConstants.INTERFACE_SAMPLING_RATE));

            testContext.completeNow();
        })));

        Assertions.assertTrue(testContext.awaitCompletion(10, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(4)
    public void testGetFlowSamplingRate(VertxTestContext testContext) throws InterruptedException
    {
        TestAPIUtil.get(TestAPIConstants.FLOW_SAMPLING_RATES + "/" + IP, testContext.succeeding(response -> testContext.verify(() ->
        {

            Assertions.assertEquals(200, response.statusCode());

            Assertions.assertNotNull(response.bodyAsJsonObject().getJsonArray(GlobalConstants.RESULT));

            testContext.completeNow();
        })));

        Assertions.assertTrue(testContext.awaitCompletion(10, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }
}

