    @Override
    public void start(Promise<Void> promise) throws Exception
    {

        if (!IntegrationProfileConfigStore.getStore().getItems().isEmpty())
        {
            vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_INTEGRATION_AUTH_TOKEN_CREATE, handler ->{

                var event = handler.body();

                var form = MultipartForm.create().attribute(USERNAME,event.getString(USERNAME)).attribute(PASSWORD,event.getString(PASSWORD)).attribute("grant_type","password");

                WebClientUtil.getWebClient().postAbs(event.getString(INTEGRATION_SERVER_URL))
                        .putHeader("Authorization",event.getString(INTEGRATION_AUTH_TOKEN)).sendMultipartForm(form,message ->{

                            if(message.succeeded())
                            {
                                var result = message.result();

                                if(result.statusCode() == 401)
                                {
                                    handler.reply(new JsonObject().put(STATUS,STATUS_FAIL).put(ERROR,"Unauthorized user"));

                                    LOGGER.warn(String.format("Unauthorized user, please check token for %s integration",event.getString(INTEGRATION_TYPE)));
                                }
                                else if (result.statusCode() == 400)
                                {
                                    handler.reply(new JsonObject().put(STATUS,STATUS_FAIL).put(ERROR,"Credential invalid"));

                                    LOGGER.warn(String.format("Credential invalid for %s integration",event.getString(INTEGRATION_TYPE)));
                                }
                                else if(result.statusCode() == 200)
                                {
                                    handler.reply(result.bodyAsJsonObject().put(STATUS,STATUS_SUCCEED));

                                    LOGGER.info(String.format("Integration with %s ,is succeed",event.getString(INTEGRATION_TYPE)));
                                }
                            }
                            else
                            {
                                handler.fail(501,message.cause().getMessage());

                                LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s",event.getString(INTEGRATION_TYPE)));
                            }
                        });
            });
        }

        promise.complete();
    }

    @Override
    public void stop(Promise<Void> promise)
    {
        promise.complete();
    }
}

