    public enum ContentType
    {
        PDF("application/pdf"),
        CSV("text/csv"),
        HTML("text/html"),
        PNG("image/png"),
        JSON("application/json"),
        EXCEL("application/vnd.ms-excel");

        private final String type;

        ContentType(String type)
        {
            this.type = type;
        }

        public static String getType(String extension)
        {
            return switch (extension.toLowerCase(Locale.ROOT))
            {
                case "pdf" -> PDF.type;

                case "csv" -> CSV.type;

                case "png" -> PNG.type;

                case "json" -> JSON.type;

                case "xlsx" -> EXCEL.type;

                default -> HTML.type;
            };
        }
    }

    public enum NotificationType
    {
        EMAIL("Email"),

        SMS("SMS"),

        WEBHOOK("Webhook"),

        PUSH("Push"),

        SNMP_TRAP("SNMP Trap"),

        SYSLOG("Syslog");

        private static final Map<String, NotificationType> VALUES = Collections.unmodifiableMap(Arrays.stream(values())
                .collect(Collectors.toMap(NotificationType::getName, e -> e)));
        private final String name;

        NotificationType(String name)
        {
            this.name = name;
        }

        public static NotificationType valueOfName(String name)
        {
            return VALUES.get(name);
        }

        public String getName()
        {
            return name;
        }
    }
