    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    public void testTraceParser(VertxTestContext testContext, TestInfo testInfo) throws Exception
    {
        var context = TestConstants.prepareParams(testInfo.getTestMethod().get().getName());

        context.put(EventBusConstants.EVENT, Base64.getDecoder().decode(context.getString(EventBusConstants.EVENT)));

        var futures = new ArrayList<Future<Void>>();

        Bootstrap.vertx().eventBus().<JsonObject>localConsumer("trace.test", message ->
        {
            var event = message.body();

            var future = Promise.<Void>promise();

            futures.add(future.future());

            LOGGER.info(String.format("%s : trace.test : event -> %s", testInfo.getTestMethod().get().getName(), event.encode()));

            Assertions.assertEquals("ft-main-server.service", event.getString(TraceConstants.SERVICE_NAME));

            Assertions.assertTrue(event.containsKey(GlobalConstants.TIME_STAMP));

            Assertions.assertEquals(context.getLong(GlobalConstants.ID), event.getLong(GlobalConstants.ID));

            Assertions.assertNotNull(AgentCacheStore.getStore().getItem(event.getLong(GlobalConstants.ID)).getJsonObject("trace.ft-main-server.service"));

            Assertions.assertTrue(AgentCacheStore.getStore().getItem(event.getLong(GlobalConstants.ID)).getJsonObject("trace.ft-main-server.service").containsKey(TraceConstants.TRACE_LAST_INGESTION_TIMESTAMP));

            future.complete();
        });

        Bootstrap.vertx().eventBus().<JsonObject>localConsumer(EVENT_SERVICE_TRACE_REGISTRATION, message ->
        {
            var event = message.body();

            var future = Promise.<Void>promise();

            futures.add(future.future());

            LOGGER.info(String.format("%s : service.trace.registration : event -> %s", testInfo.getTestMethod().get().getName(), event.encode()));

            Assertions.assertEquals("ft-main-server.service", event.getString(TraceConstants.SERVICE_NAME));

            Assertions.assertTrue(event.containsKey(GlobalConstants.TIME_STAMP));

            future.complete();
        });

        Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_TRACE, context);

        Future.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                LOGGER.info(String.format("%s : test case completed...", testInfo.getTestMethod().get().getName()));

                testContext.completeNow();
            }
            else
            {
                LOGGER.warn(String.format("%s : failed reason : %s", testInfo.getTestMethod().get().getName(), result.cause().getMessage()));

                testContext.failNow(result.cause());
            }
        });
    }

