```
package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.*;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;

import java.io.File;
import java.util.*;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.datastore.DatastoreConstants.BATCH_FILE;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.nms.NMSConstants.CACHE_NAME;

public class ConfigDatastoreObserverManager extends AbstractVerticle
{
    private final Logger LOGGER;
    private final TreeSet<String> eventFiles = new TreeSet<>();
    private final Map<String, Integer> offsets = new TreeMap<>();
    private final Map<String, String> deployedRouters = new HashMap<>();
    private final Map<String, Long> ticks = new HashMap<>();
    private final String eventType;
    private final String clazz;
    private final int eventRouters;
    private final boolean blocking;
    private String storeDirectory;
    private static final long MAX_BUFFER_BYTES = 1048576L;

    public ConfigDatastoreObserverManager(String eventType, int eventRouters, String clazz, boolean blocking)
    {
        this.blocking = blocking;

        this.eventType = eventType;

        this.clazz = clazz;

        this.eventRouters = eventRouters >= 0 ? eventRouters : 1;

        this.LOGGER = new Logger(ConfigDatastoreObserverManager.class, MOTADATA_DB, String.format("Observer Config DB Manager:(%s)", eventType));
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var futures = new ArrayList<Future>();

        storeDirectory = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.EVENT_DIR + GlobalConstants.PATH_SEPARATOR
                + EventBusConstants.replace(eventType);

        for (var eventRouter = 0; eventRouter < this.eventRouters; eventRouter++)
        {
            load(eventRouter);

            var future = Promise.<Void>promise();

            var router = eventType + GlobalConstants.DOT_SEPARATOR + eventRouter;

            futures.add(future.future());

            if (blocking)
            {
                vertx.deployVerticle(clazz, new DeploymentOptions().setConfig(new JsonObject().put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router)).put(EVENT_TYPE, router)).setWorker(true).setWorkerPoolSize(1).setWorkerPoolName("wp." + router), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router.replaceAll(EventBusConstants.EVENT_CONFIG_DB_WRITE, EVENT_CONFIG_DB_CREATE), message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
            else
            {
                vertx.deployVerticle(clazz, new DeploymentOptions()
                        .setConfig(new JsonObject()
                                .put(EventBusConstants.EVENT_ROUTER_CONFIG, EventBusConstants.replace(router))
                                .put(EVENT_TYPE, router)), result ->
                {
                    if (result.succeeded())
                    {
                        future.complete();

                        deployedRouters.put(router, result.result());

                        vertx.eventBus().<String>localConsumer(router.replaceAll(EventBusConstants.EVENT_DATASTORE_WRITE, EVENT_DATASTORE_CREATE), message -> eventFiles.add(message.body()));
                    }
                    else
                    {
                        future.fail(result.cause());
                    }
                });
            }
        }

        CompositeFuture.join(futures).onComplete(result ->
        {
            if (result.succeeded())
            {
                var destination = eventType.replaceAll(EVENT_CONFIG_DB_WRITE, EVENT_CACHE_DB_READ);

                vertx.setPeriodic(120 * 1000, handler -> purge(eventType.replaceAll(EventBusConstants.EVENT_CONFIG_DB_WRITE, EVENT_CONFIG_DB_PURGE)));

                // config event read and write event

                vertx.eventBus().<JsonObject>localConsumer(eventType.replaceAll(EVENT_CONFIG_DB_WRITE, EVENT_CONFIG_DB_READ), message ->
                {
                    try
                    {
                        var bytes = 0L;

                        var futurePromise = Promise.<Void>promise();

                        var requests = new ArrayList<JsonObject>();

                        for (var eventFile : eventFiles)
                        {
                            var timestamp = CommonUtil.getLong(eventFile.split(GlobalConstants.DASH_SEPARATOR)[0]);

                            if ((DateTimeUtil.currentSeconds() - timestamp) > 5 && bytes <= MAX_BUFFER_BYTES)
                            {
                                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + eventFile + ".dat");

                                if (file.exists() && file.length() > 0)
                                {
                                    var length = CommonUtil.getInteger(file.length());

                                    if (!offsets.containsKey(eventFile))
                                    {
                                        requests.add(new JsonObject()
                                                .put(EVENT_TIMESTAMP,timestamp)
                                                .put(EVENT_TYPE, destination + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                .put(EVENT_TOPIC, EVENT_HA_OBSERVER)
                                                .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                        offsets.put(eventFile, length);

                                        ticks.put(eventFile, System.currentTimeMillis());

                                        bytes += length;
                                    }
                                    else
                                    {
                                        var currentOffset = offsets.get(eventFile);

                                        if (currentOffset < length)
                                        {
                                            length = CommonUtil.getInteger(length - currentOffset);

                                            requests.add(new JsonObject()
                                                    .put(EVENT_TYPE, destination + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters))
                                                    .put(EVENT_TIMESTAMP,timestamp)
                                                    .put(EVENT_TOPIC, EVENT_HA_OBSERVER)
                                                    .put(BATCH_FILE, eventFile).put(EVENT_CONTEXT, new byte[length]));

                                            offsets.put(eventFile, length + currentOffset);

                                            bytes += length;
                                        }
                                    }
                                }
                            }
                        }

                        if (!requests.isEmpty())
                        {
                            var requestFutures = new ArrayList<Future>();

                            LOGGER.debug(String.format("db store qualified %s files total bytes %s", requests.size(), bytes));

                            requests.forEach(item ->
                            {
                                var future = Promise.<Void>promise();

                                requestFutures.add(future.future());

                                Bootstrap.vertx().eventBus().<JsonObject>request(item.getString(EVENT_TYPE), item, handler -> future.complete());
                            });

                            CompositeFuture.join(requestFutures).onComplete(handler ->
                            {
                                LOGGER.debug(String.format("db store %s files received response", requests.size()));

                                requests.forEach(item ->
                                {
                                    if (item.containsKey(EVENT_CONTEXT))
                                    {
                                        if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                                        {
                                            vertx.eventBus().send("test.datastore.event", item);
                                        }

                                        vertx.eventBus().send(EVENT_HA_OBSERVER, new JsonObject().mergeIn(item)
                                                .put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_WRITE)
                                                .put(EVENT_COPY_REQUIRED, false));

                                        vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject().mergeIn(item)
                                                .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                                .put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_FLUSH));

                                        LOGGER.debug(String.format("db store %s file send to datastore", item.getString(BATCH_FILE)));
                                    }
                                });

                                futurePromise.complete();
                            });
                        }
                        else
                        {
                            vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject()
                                    .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                                    .put(EVENT_COPY_REQUIRED, false)
                                    .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                    .put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_ACKNOWLEDGEMENT));
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).exceptionHandler(LOGGER::error);

                vertx.eventBus().<byte[]>localConsumer(eventType, message ->
                {
                    try
                    {
                        vertx.eventBus().send(eventType + GlobalConstants.DOT_SEPARATOR + (ByteUtil.readLongValue(message.body()) % eventRouters), message.body()); //send event to writer
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).exceptionHandler(LOGGER::error);

                //cache event read and write consumer

                vertx.eventBus().<JsonObject>localConsumer(eventType.replaceAll(EVENT_CONFIG_DB_WRITE, EVENT_CACHE_DB_READ), event ->
                {
                    var caches = new File(storeDirectory).listFiles();

                    if (caches != null)
                    {
                        for (var cache : caches)
                        {
                            if (!cache.getName().endsWith(".json") && !cache.getName().endsWith(".dat"))
                            {
                                vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject()
                                        .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                                        .put(EVENT_COPY_REQUIRED, false)
                                        .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, event.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                        .put(EVENT_TYPE, EventBusConstants.EVENT_CACHE_SYNC_FLUSH)
                                        .put(CACHE_NAME, cache.getName())
                                        .put(RESULT, vertx.fileSystem().readFileBlocking(storeDirectory + PATH_SEPARATOR + cache.getName())));
                            }
                        }

                        LOGGER.info(String.format("%s caches sent to %s ",caches.length,event.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID)));
                    }
                });

                vertx.eventBus().<JsonObject>localConsumer(eventType.replaceAll(EVENT_CONFIG_DB_WRITE, EVENT_CACHE_DB_WRITE), event ->
                {
                    try
                    {
                        var context = event.body();

                        LOGGER.info(String.format("received updated cache file %s ",context.getString(CACHE_NAME)));

                        Bootstrap.vertx().fileSystem().writeFileBlocking(storeDirectory + PATH_SEPARATOR + context.getString(CACHE_NAME), Buffer.buffer(context.getBinary(RESULT)));
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                });

                promise.complete();
            }
            else
            {
                promise.fail(result.cause());
            }
        });
    }

    private void purge(String removeTopic)
    {
        try
        {
            for (var iterator = eventFiles.iterator(); iterator.hasNext();)
            {
                var entry = iterator.next();

                var timestamp = CommonUtil.getLong(entry.split(GlobalConstants.DASH_SEPARATOR)[0]);

                var file = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + (timestamp % eventRouters) + GlobalConstants.PATH_SEPARATOR + entry + ".dat");

                if (file.exists() && offsets.containsKey(entry) && offsets.get(entry) == file.length())
                {
                    offsets.remove(entry);

                    ticks.remove(entry);

                    iterator.remove();

                    vertx.eventBus().send(removeTopic + GlobalConstants.DOT_SEPARATOR + (timestamp % eventRouters), entry);

                    LOGGER.debug(String.format("event db store %s file deleted because file reach point reach EOF", entry));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load(int eventRouter)
    {
        try
        {
            var files = new File(storeDirectory + GlobalConstants.DASH_SEPARATOR + eventRouter).listFiles();

            if (files != null)
            {
                Arrays.stream(files).filter(file -> file.getName().endsWith(".dat")).forEach(file -> eventFiles.add(file.getName().split(GlobalConstants.DOT_SEPARATOR_ESCAPE)[0]));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            var futures = new ArrayList<Future>();

            for (var deploymentId : deployedRouters.values())
            {
                var future = Promise.<Void>promise();

                futures.add(future.future());

                vertx.undeploy(deploymentId, handler -> future.complete());
            }

            CompositeFuture.join(futures).onComplete(handler -> promise.complete());
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            if (!promise.future().isComplete())
            {
                promise.fail(exception);
            }
        }
    }
}


