package com.mindarray;

import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.*;
import com.mindarray.util.*;
import static com.mindarray.Bootstrap.startEngine;
import static com.mindarray.Bootstrap.stop;
import static com.mindarray.eventbus.EventBusConstants.*;

public class BootstrapObserver
{
    private static final Logger LOGGER = new Logger(BootstrapObserver.class, GlobalConstants.MOTADATA_SYSTEM, "Bootstrap Observer");

    public void start()
    {
        try
        {
            DBConstants.loadDBConfigs();

            Bootstrap.logSystemConfig();

            ProcessUtil.setProcessors();

            startEngine(new EventPublisher(MotadataConfigUtil.getMotadataObserverEventPublisherPort(), "Motadata Observer Publisher"), EventPublisher.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventPublisherPort(), null, EVENT_PUBLICATION_MOTADATA_OBSERVER)
                .compose(future -> startEngine(new EventSubscriber(MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), "Motadata Observer Subscriber"), EventSubscriber.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), null))
                .compose(future -> startEngine(new EventSubscriber(MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), "Motadata Observer Subscriber"), EventSubscriber.class.getSimpleName() + " " + MotadataConfigUtil.getMotadataObserverEventSubscriberPort(), null))
                .onComplete(response ->
                {
                    if (response.succeeded())
                    {
                        EventBusConstants.setRemoteEventProcessorRegistrationId();

                        LOGGER.info(String.format(InfoMessageConstants.MOTADATA_ENGINE_START_SUCCEEDED, GlobalConstants.InstallationMode.STANDALONE));
                    }
                    else
                    {
                        stop(response.cause());
                    }
                });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
